#include <iostream>

int main() {
    // Create and fill a list (e.g., std::vector) with characters 'a' through 'z'
    std::vector<char> charList(26);
    for (char c = 'a'; c <= 'z'; ++c) {
        charList[c - 'a'] = c;  // Fill the vector
    }

    // Print the elements using a loop, with std::endl for flushing
    for (const auto& elem : charList) {
        std::cout << elem << ' ';  // Output each character followed by a space
    }
    std::cout << std::endl;  // Insert newline and flush the buffer
    return 0;
}
